import Foundation

/// V1's catalogue: the owner's exercises and routines bundled with the build
/// (`Resources/Bundled`, generated by `scripts/examples.py`), plus the
/// exercises added on the phone. A record that does not decode is skipped and
/// listed in `Catalog.unreadable`; it never stops the rest loading.
public final class BundledCatalog: CatalogSource, @unchecked Sendable {
    public let codec: RecordCodec
    private let bundle: Bundle
    private let localExercises: LocalExercises?
    // Guards `continuations`; `@unchecked Sendable` rests on it.
    private let lock = NSLock()
    private var continuations: [UUID: AsyncStream<Catalog>.Continuation] = [:]

    /// - Parameters:
    ///   - localExercises: the phone's own exercises; nil leaves them out.
    ///   - bundle: where `Bundled/` lives; nil is WorkoutsCore's resource bundle.
    public init(localExercises: LocalExercises? = nil, codec: RecordCodec = RecordCodec(), bundle: Bundle? = nil) {
        self.localExercises = localExercises
        self.codec = codec
        self.bundle = bundle ?? .module
    }

    /// WorkoutsCore's resource bundle.
    public static var resourceBundle: Bundle { .module }

    public func load() async throws -> Catalog {
        try loadNow()
    }

    /// The catalogue, read synchronously. Throws only when a bundled file is
    /// missing or is not a records file, which is a build fault.
    public func loadNow() throws -> Catalog {
        var catalog = Catalog()
        for record in try bundledRecords("exercises") {
            do {
                let exercise = try codec.decodeExercise(record)
                catalog.exercises[exercise.id] = exercise
            } catch {
                catalog.unreadable.append(UnreadableRecord(source: "Bundled/exercises.json", kind: record.kind, id: record.id, reason: error.description))
            }
        }
        for record in try bundledRecords("routines") {
            do {
                let routine = try codec.decodeRoutine(record)
                catalog.routines[routine.id] = routine
            } catch {
                catalog.unreadable.append(UnreadableRecord(source: "Bundled/routines.json", kind: record.kind, id: record.id, reason: error.description))
            }
        }
        if let localExercises {
            do {
                let local = try localExercises.load()
                catalog.unreadable += local.unreadable
                for exercise in local.exercises {
                    // A new exercise's slug avoids taken ids; should one collide
                    // anyway, the bundled exercise, which routines name, wins.
                    guard catalog.exercises[exercise.id] == nil else {
                        catalog.unreadable.append(UnreadableRecord(source: LocalExercises.fileName, kind: codec.kinds.exercise, id: exercise.id.rawValue, reason: "a bundled exercise has this id"))
                        continue
                    }
                    catalog.exercises[exercise.id] = exercise
                }
            } catch {
                catalog.unreadable.append(UnreadableRecord(source: LocalExercises.fileName, reason: String(describing: error)))
            }
        }
        return catalog
    }

    public func updates() -> AsyncStream<Catalog> {
        let (stream, continuation) = AsyncStream.makeStream(of: Catalog.self, bufferingPolicy: .bufferingNewest(1))
        let key = UUID()
        lock.withLock { continuations[key] = continuation }
        continuation.onTermination = { [weak self] _ in
            guard let self else { return }
            _ = lock.withLock { self.continuations.removeValue(forKey: key) }
        }
        return stream
    }

    /// Saves an exercise added on the phone and yields the new catalogue to
    /// every `updates()` stream.
    @discardableResult
    public func addLocalExercise(_ exercise: Exercise) throws -> Catalog {
        guard let localExercises else { throw CatalogError.noLocalStore }
        var local = exercise
        local.isLocal = true
        try localExercises.add(local)
        let catalog = try loadNow()
        let listeners = lock.withLock { Array(continuations.values) }
        for continuation in listeners {
            continuation.yield(catalog)
        }
        return catalog
    }

    private func bundledRecords(_ name: String) throws -> [FlatRecord] {
        guard let url = bundle.url(forResource: name, withExtension: "json", subdirectory: "Bundled") else {
            throw CatalogError.missingResource("Bundled/\(name).json")
        }
        return try JSONDecoder().decode(RecordFile.self, from: Data(contentsOf: url)).records
    }
}

public enum CatalogError: Error, Hashable, Sendable {
    /// A bundled file is not in the build.
    case missingResource(String)
    /// The catalogue was made without a local exercises file.
    case noLocalStore
}
